<?php
namespace App\Http\Controllers; use App\Models\Category; use Illuminate\Http\Request; use Illuminate\Support\Str;
class CategoryController extends Controller {public function index(Request $r){$q=$r->string('q')->toString();$categories=Category::with('parent')->when($q,fn($x)=>$x->where('name','like',"%$q%"))->orderBy('name')->paginate(15)->withQueryString();return view('admin.categories.index',compact('categories','q'));}public function create(){return view('admin.categories.form',['category'=>new Category,'parents'=>Category::orderBy('name')->get()]);}public function store(Request $r){$d=$r->validate(['parent_id'=>'nullable|exists:categories,category_id','name'=>'required|string|max:100','slug'=>'nullable|string|max:150|unique:categories,slug','description'=>'nullable|string']);$d['slug']=$d['slug']?:Str::slug($d['name']);Category::create($d);return redirect()->route('admin.categories.index')->with('success','Category created successfully.');}public function edit(Category $category){return view('admin.categories.form',['category'=>$category,'parents'=>Category::where('category_id','!=',$category->category_id)->orderBy('name')->get()]);}public function update(Request $r,Category $category){$d=$r->validate(['parent_id'=>'nullable|exists:categories,category_id','name'=>'required|string|max:100','slug'=>'nullable|string|max:150|unique:categories,slug,'.$category->category_id.',category_id','description'=>'nullable|string']);$d['slug']=$d['slug']?:Str::slug($d['name']);$category->update($d);return redirect()->route('admin.categories.index')->with('success','Category updated successfully.');}public function destroy(Category $category){if($category->products()->exists()||$category->children()->exists())return back()->with('error','Category cannot be deleted while it is in use.');$category->delete();return back()->with('success','Category deleted.');}}
